}

#include <iostream>
#include <string>
using namespace std;

const int PASS_MARK = 40;

void printBar(int score) {
    cout << score << " | ";
    for (int i = 1; i <= score / 10; i++) {
        cout << "*";
    }
    cout << endl;
}

string verdict(int score) {
    return score >= PASS_MARK ? "pass" : "fail";
}

double average(int total, int count) {
    if (count == 0) {
        return 0.0;
    }
    return static_cast<double>(total) / count;
}

int main() {
    cout << "How many scores? ";
    int count;
    cin >> count;

    int total = 0;
    for (int i = 1; i <= count; i++) {
        cout << "Score " << i << "? ";
        int score;
        cin >> score;
        total += score;
        printBar(score);
        cout << verdict(score) << endl;
    }

    cout << "Average: " << average(total, count) << endl;
    return 0;
}

